/// Ends this generation: every waiter gets `Io`, the channel closes (a live supervisor then stops
/// every tree, as on host death; one that does not exit within `bound` is killed by identity, or, where
/// its identity cannot be checked, left running and named in the error), and later calls fail at once.
/// Never blocks.
pub(super) fn die(&self, why: String) {
    let why = match self.chan.can_end() {
        true => why,
        false => format!(
            "{why}; should it not exit, it is abandoned: its identity cannot be checked here (no pidfd on \
             Linux, no start time on macOS), so ending it could hit another process"
        ),
    };

pub(super) fn kill(&self) -> Kill {
    use std::sync::atomic::Ordering;
    if self.exited.load(Ordering::Acquire) || self.exit_fired() {
        self.exited.store(true, Ordering::Release);
        return Kill::Gone;
    }
    match (self.start, started(self.pid)) {
        (None, _) => Kill::Abandoned,
        (Some(then), Some(now)) if then == now => {
            // The number still names the process we started (same start time). Residual window: it could
            // exit, be reaped by someone else and its number be reused in the microseconds between this
            // check and the signal; declared in GUARANTEES.md, row "A stuck supervisor".
            // SAFETY: `kill` changes no memory; the target was just checked as our supervisor.
            unsafe { libc::kill(self.pid, libc::SIGKILL) };
            Kill::Sent
        }

